import { chinaLocalDateTimeToDate, formatChinaDateTime } from "./time";

export type RiskAlert = { type: "ETB_REVIEW" | "DEADLINE" | "PLAN_RISK"; severity: "CRITICAL" | "WARNING"; title: string; detail: string; href: string; orderId: string };
type RiskOrder = { id: string; soNumber: string; etbNeedsReview: boolean; openingText: string | null; siCutoffText: string | null; forwarderSiCutoffText?: string | null; vgmCutoffText: string | null; portCutoffText: string | null; plans: Array<{ scheduledAt: Date; status: string }> };

function parseSourceTime(value: string) {
  const numeric = value.match(/(\d{1,2})[/-](\d{1,2})[/-](\d{4})\s+(\d{1,2}):(\d{2})/);
  if (numeric) return chinaLocalDateTimeToDate(`${numeric[3]}-${numeric[2].padStart(2, "0")}-${numeric[1].padStart(2, "0")}T${numeric[4].padStart(2, "0")}:${numeric[5]}`);
  const named = value.match(/(\d{1,2})[-/]([A-Z]{3,4})[-/](\d{2,4})\s+(\d{1,2}):(\d{2})/i);
  if (!named) return;
  const months: Record<string, string> = { JAN: "01", FEB: "02", MAR: "03", APR: "04", MAY: "05", JUN: "06", JUL: "07", AUG: "08", SEP: "09", SEPT: "09", OCT: "10", NOV: "11", DEC: "12" };
  const month = months[named[2].toUpperCase()];
  if (!month) return;
  return chinaLocalDateTimeToDate(`${named[3].length === 2 ? `20${named[3]}` : named[3]}-${month}-${named[1].padStart(2, "0")}T${named[4].padStart(2, "0")}:${named[5]}`);
}

function nearestSi(order: RiskOrder) {
  const candidates = ([
    { label: "货代补料截止", value: order.forwarderSiCutoffText },
    { label: "船公司补料截止", value: order.siCutoffText },
  ] as const)
    .flatMap(item => {
      const deadline = item.value ? parseSourceTime(item.value) : undefined;
      return deadline ? [{ label: item.label, value: item.value!, deadline }] : [];
    });
  return candidates.sort((left, right) => left.deadline.valueOf() - right.deadline.valueOf())[0];
}

export function evaluateRiskAlerts(orders: RiskOrder[], now = new Date()): RiskAlert[] {
  const alerts: RiskAlert[] = [];
  for (const order of orders) {
    const href = `/orders/${order.id}`;
    if (order.etbNeedsReview) alerts.push({ type: "ETB_REVIEW", severity: "WARNING", title: `${order.soNumber} 的 ETB 待核实`, detail: "船期出现新观测，业务采用时间尚未被自动覆盖。", href, orderId: order.id });
    const deadlines = [
      nearestSi(order),
      ...([ ["开仓", order.openingText], ["VGM 截止", order.vgmCutoffText], ["截关", order.portCutoffText] ] as const).map(([label, value]) => ({ label, value, deadline: value ? parseSourceTime(value) : undefined })),
    ];
    for (const item of deadlines) {
      if (!item?.deadline) continue;
      const hours = (item.deadline.valueOf() - now.valueOf()) / 3_600_000;
      if (hours < 0 || hours > 48) continue;
      alerts.push({ type: "DEADLINE", severity: hours <= 12 ? "CRITICAL" : "WARNING", title: `${order.soNumber}：${item.label}临近`, detail: `${formatChinaDateTime(item.deadline)}（剩余约 ${Math.max(0, Math.ceil(hours))} 小时）`, href, orderId: order.id });
    }
    for (const plan of order.plans.filter(plan => ["DRAFT", "CONFIRMED"].includes(plan.status))) {
      const hours = (plan.scheduledAt.valueOf() - now.valueOf()) / 3_600_000;
      if (hours >= 0 && hours <= 24) alerts.push({ type: "PLAN_RISK", severity: "WARNING", title: `${order.soNumber}：装柜计划临近`, detail: `计划时间 ${formatChinaDateTime(plan.scheduledAt)}，请优先以更近的补料截关时间安排。`, href, orderId: order.id });
    }
  }
  return alerts.sort((a, b) => a.severity === b.severity ? 0 : a.severity === "CRITICAL" ? -1 : 1);
}
